Body:
For anyone hitting the subagent TPS collapse or ballooning prompt tokens on multi-turn reasoning models (especially with open-weights / Chinese models like Minimax, DeepSeek-R1, Qwen, GLM), here is a lightweight native OpenCode V2 plugin workaround that:

1. **Keeps live streaming reasoning visible** on the terminal in real-time.
2. **Scrubs past reasoning on subsequent turns** so prompt history stays lean (~20k-40k tokens instead of quadratic 300k+ bloat).
3. **Selectively retains reasoning on tool-call turns** (critical: models like Minimax/DeepSeek will return HTTP 500 `"Provider returned error"` if reasoning is stripped from an assistant turn containing `tool_calls`).

### How to use:

1. Save to `~/.config/opencode2/plugins/collapse-reasoning.ts`:

```typescript
import { Plugin } from "@opencode-ai/plugin";

function cleanText(text: string): string {
  if (!text) return "";
  return text
    .replace(/<(?:think|thought|thinking)>[\s\S]*?<\/(?:think|thought|thinking)>/gi, "")
    .replace(/\[(?:think|thought|thinking)\][\s\S]*?\[\/(?:think|thought|thinking)\]/gi, "")
    .trim();
}

function cleanPart(part: unknown): unknown {
  if (!part || typeof part !== "object") return part;
  const obj = part as Record<string, unknown>;
  if (obj.type === "reasoning") return null;
  if (obj.type === "text" && typeof obj.text === "string") {
    return { ...obj, text: cleanText(obj.text) };
  }
  return part;
}

function hasToolCalls(msg: Record<string, unknown>): boolean {
  if (Array.isArray(msg.tool_calls) && msg.tool_calls.length > 0) return true;
  if (Array.isArray(msg.content)) {
    return msg.content.some((p: any) =>
      p && (p.type === "tool-call" || p.type === "tool_call" ||
            p.type === "tool-result" || p.type === "tool_result")
    );
  }
  if (typeof msg.content === "string") {
    return (
      msg.content.includes("<tool_call>") ||
      msg.content.includes("<invoke") ||
      msg.content.includes("<function=")
    );
  }
  return false;
}

function cleanMessage(msg: unknown): unknown {
  if (!msg || typeof msg !== "object") return msg;
  const m = msg as Record<string, unknown>;
  if (m.role !== "assistant") return msg;
  if (hasToolCalls(m)) return msg; // Preserve reasoning for tool calls to avoid upstream 500s
  if (Array.isArray(m.content)) {
    const cleanedParts = m.content.map(cleanPart).filter((p) => p !== null);
    return { ...m, content: cleanedParts };
  }
  if (typeof m.content === "string") {
    return { ...m, content: cleanText(m.content) };
  }
  return msg;
}

export default Plugin.define({
  id: "collapse-reasoning",
  setup: async (ctx) => {
    await ctx.session.hook("context", async (event) => {
      try {
        if (Array.isArray(event.messages)) {
          event.messages = event.messages.map(cleanMessage) as typeof event.messages;
        }
      } catch (err) {
        console.error("[collapse-reasoning] hook error:", err);
      }
    });
  },
});
```

2. Register the plugin in `~/.config/opencode2/config.json`:
```json
{
  "plugins": [
    "./plugins/collapse-reasoning.ts"
  ]
}
```

*(Sharing as a standalone interim workaround for anyone stuck on this before upstream patches the DB schema).*
